(function(root){
'use strict';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ids={catalog:'catalog',avatar:'avatar','speaker-name':'speaker-name','speaker-subtitle':'speaker-subtitle',guide:'back',context:'context',journey:'journey',thread:'thread',suggestions:'suggestions',composer:'composer',question:'draft',dictate:'mic','dictation-status':'status','guest-invitation':'guest'};
function prefix(html){return html.replace(/(id|for)="([^"]+)"/g,(all,attr,id)=>attr+'="historical-'+(ids[id]||id)+'"');}
function shell(historical=false){if(historical==='recorded')return recordedShell();let html=`
<section class="explore" aria-label="Explore football">
<div class="eyebrow">EXPLORE YOUR FOOTBALL</div><h1>Who will you<br><em>talk to next?</em></h1><p class="intro">Revisit a match. Hear a club’s side.<br>Meet the ground that brings it together.</p>
<nav class="sections" aria-label="Explore subjects"><button data-section="matches" aria-pressed="true">Matches</button><button data-section="clubs" aria-pressed="false">Clubs</button><button data-section="stadiums" aria-pressed="false">Stadiums</button></nav>
<div id="catalog"></div>
<footer class="explore-footer"><span class="little-star">✳</span><p>One football world. Different voices.<br><strong>Where will you take the conversation?</strong></p></footer>
</section>
<section class="conversation" aria-label="Conversation">
<div class="conversation-bar"><div><span class="avatar" id="avatar">✳</span><div><strong id="speaker-name">Your Matchmate</strong><small id="speaker-subtitle">Your personal football guide</small></div></div><button id="guide" class="text-button" hidden>← Your guide</button></div>
<div id="context"></div><div id="journey" aria-live="polite"></div><div id="thread" role="log" aria-live="polite" aria-label="Conversation messages"></div><div id="suggestions" aria-label="Suggested questions"></div>
<form id="composer"><label class="sr-only" for="question">Your message</label><input id="question" autocomplete="off" placeholder="Type or dictate a message…"><button id="dictate" type="button" aria-label="Dictate message" aria-pressed="false" title="Dictate message"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><rect x="9" y="2" width="6" height="12" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v3M8 22h8"/></svg></button><button aria-label="Send message" type="submit">↑</button></form>
<div id="dictation-status" role="status" aria-live="polite">Dictation uses your browser’s speech service. Review before sending.</div>
<div class="composer-note"><span>Example replies in this preview</span><span>Text first. Voice is next. ◌</span></div>
<div id="guest-invitation" aria-live="polite"></div>
</section>
`;
const conversation=html.indexOf('<section class="conversation"');html=html.slice(conversation)+html.slice(0,conversation);
if(!historical)return html;
html=html.replace('<div id="journey"','<div id="pitch-slot"></div><div id="journey"');
html=prefix(html).replace('← Your guide','← Back to the season').replace('id="historical-back" class="text-button" hidden','id="historical-back" class="text-button"').replace(/data-section="([^"]+)"/g,(_,value)=>value==='matches'?'aria-current="page"':'disabled title="Not available in historical match coverage"').replace('Your personal football guide','Historical result · local computed answers').replace('Your Matchmate','The match').replace('id="historical-avatar">✳','id="historical-avatar">↗').replace('Example replies in this preview','Local computed facts · no AI').replace('id="historical-guest"','id="historical-guest" hidden');
html=html.replace('<button aria-label="Send message"','<button id="historical-send" aria-label="Send message"');return html;}
function pitch({model,time=0,expanded=true,unavailable=false,home='',away='',score='',recorded=false}){if(recorded)return recordedPitch(model);let html=`<details class="replay" ${expanded?'open':''}><summary>On the pitch <span>${unavailable?'Position data unavailable':'20-second synthetic replay'}</span></summary><div class="replay-body"><div class="replay-grid"><div class="pitch-panel"><div class="pitch-meta"><span>${unavailable?esc(home)+' → <b>'+esc(score)+'</b> ← '+esc(away):'HARBOUR → <b>1–1</b> ← RIVERSIDE'}</span><strong id="replay-time"></strong></div><div class="pitch" role="group" aria-label="Overhead football pitch. Choose a player."><div class="pitch-lines" aria-hidden="true"><i class="centre-circle"></i><i class="halfway"></i><i class="box left"></i><i class="box right"></i></div>${model.players.map(p=>`<button class="player ${p.team}" id="player-${p.id}" data-player="${p.id}" aria-label="Select ${p.name}, ${p.role}" aria-pressed="false">${p.number}</button>`).join('')}<svg class="ball-trail" viewBox="0 0 105 68" preserveAspectRatio="none" aria-hidden="true"><polyline id="ball-path" /></svg><span id="ball-halo" aria-hidden="true"></span><span id="replay-ball" aria-hidden="true"></span></div>${unavailable?'<p class="pitch-empty-notice">Player positions unavailable for this match</p>':''}<div class="pitch-selection"><span id="selected-player"></span><label class="sr-only" for="replay-player">Focus player</label><select id="replay-player">${model.players.map(p=>`<option value="${p.id}">${p.name}</option>`).join('')}</select></div><div class="ball-controls"><button id="follow-ball" aria-pressed="false">Follow the ball</button><span id="ball-readout"></span></div><label class="sr-only" for="replay-range">Replay time</label><input id="replay-range" type="range" min="0" max="20" step="0.1" value="${time}"><div class="replay-controls"><button id="replay-play">▶ Play</button><button id="replay-prev" aria-label="Previous event">← Event</button><button id="replay-next" aria-label="Next event">Event →</button><button id="replay-edge">${unavailable?'Full time':'65:00 · Latest'}</button></div><div class="event-markers">${model.events.map(e=>`<button data-replay-time="${e.time}" aria-label="Jump to ${model.clock(e.time)}">${model.clock(e.time)}</button>`).join('')}</div><p id="replay-event" aria-live="off"></p></div><section class="player-stats" aria-label="Player statistics"><div class="stats-heading"><strong>Players at <span id="stats-clock"></span></strong><div><button data-stats-team="H">${unavailable?esc(home):'Harbour'}</button><button data-stats-team="R">${unavailable?esc(away):'Riverside'}</button></div></div><p class="stats-key">${unavailable?'Lineup data not loaded':'Match totals · speed now · select a player'}</p><div class="stats-scroll" tabindex="0" role="region" aria-label="Player statistics table, scroll for more players"><table><thead><tr><th scope="col">Player</th><th scope="col">Metres</th><th scope="col">km/h</th><th scope="col">Pass ✓</th><th scope="col">Pass ×</th><th scope="col">Tkl</th><th scope="col">Int</th></tr></thead><tbody id="stats-rows">${unavailable?'<tr><td colspan="7">Lineup data not loaded. Player statistics unavailable.</td></tr>':''}</tbody></table></div><small>${unavailable?'No lineup, position or tracking data is attached to this match.':'Synthetic totals at 64:40 + this passage. Pass ✓ completed; Pass × unsuccessful; Tkl tackles won; Int interceptions. In-flight passes stay pending. No defensive actions occur in this clip.'}</small></section></div><button class="ask-moment" id="ask-moment">Ask about this moment ↗</button><small>${unavailable?'Full-time result only · Replay unavailable.':'Authored player paths · Not real tracking or a live feed. Only events up to the cursor inform the answer.'}</small></div></details>`;
if(unavailable){html=html.replace(/<svg class="ball-trail"[\s\S]*?<\/svg>/,'').replace(/<span id="(?:ball-halo|replay-ball)"[^>]*><\/span>/g,'').replace('Overhead football pitch. Choose a player.','Empty football pitch. Player positions unavailable.').replace('max="20"','max="1"').replace('Focus player','Player data unavailable').replace('Replay time','Replay unavailable').replace('Player statistics table, scroll for more players','Player statistics unavailable').replace(/data-stats-team/g,'data-historical-stats-team');
html=prefix(html).replace(/<(button|select|input)\b/g,'<$1 disabled').replace('id="historical-replay-time"></strong>','id="historical-replay-time">FT</strong>').replace('id="historical-stats-clock"></span>','id="historical-stats-clock">full time</span>');}
return html;}
function recordedShell(){return shell(true).replaceAll('historical-','recorded-').replace('Historical result · local computed answers','Recorded sample · local grounded answers').replaceAll('historical match coverage','recorded sample coverage').replace('Local computed facts · no AI','Local sample facts · no AI').replace(/<button id="recorded-mic"[\s\S]*?<\/button>/,'').replace('Type or dictate a message…','Ask about this moment or player…').replace('Dictation uses your browser’s speech service. Review before sending.','Answers describe the selected sample only. No AI or live connection.').replace('Text first. Voice is next. ◌','Retrospective, source-derived');}
function recordedPitch(model){const s=model.sample;return `<details class="replay recorded-replay" open><summary>On the pitch <span>Recorded tracking replay · First half 01:00–04:00</span></summary><div class="replay-body"><div class="replay-grid"><div class="pitch-panel"><div class="pitch-meta"><span>${esc(s.home.name)} → · ← ${esc(s.away.name)}</span><strong id="recorded-time"></strong></div><div class="pitch recorded-pitch" role="group" aria-label="Recorded football positions. Display axes positive x right, positive y up. Choose a player."><div class="recorded-field" aria-hidden="true"><div class="pitch-lines"><i class="centre-circle"></i><i class="halfway"></i><i class="box left"></i><i class="box right"></i></div></div>${model.roster.map(p=>`<button class="recorded-marker ${p.team}" id="recorded-player-${p.id}" data-recorded-player="${p.id}" aria-pressed="false" hidden><span>${esc(p.number??'?')}</span><b class="quality-badge" aria-hidden="true">?</b></button>`).join('')}<span id="recorded-ball" class="recorded-ball" role="img" hidden></span><p id="recorded-pitch-empty" hidden>Positions unavailable at this moment</p></div><div class="pitch-selection"><span id="recorded-selected-player"></span><label class="sr-only" for="recorded-player">Focus player</label><select id="recorded-player">${model.roster.map(p=>`<option value="${p.id}">${esc(p.name)} · ${esc(p.teamName)} · ${esc(p.number??'?')}</option>`).join('')}</select></div><p id="recorded-position-detail" class="recorded-readout"></p><p id="recorded-ball-status" class="recorded-readout"></p></div><section class="player-stats recorded-roster" aria-label="Source roster and position availability"><div class="stats-heading"><strong>Players at <span id="recorded-roster-clock"></span></strong><div><button data-recorded-team="home">${esc(s.home.name)}</button><button data-recorded-team="away">${esc(s.away.name)}</button></div></div><p class="stats-key">Source roster · select a player, including during gaps</p><table><thead><tr><th scope="col">Player</th><th scope="col">Position quality</th></tr></thead><tbody>${model.roster.map(p=>`<tr id="recorded-row-${p.id}"><th scope="row"><button data-recorded-player="${p.id}" aria-pressed="false"><span class="recorded-shirt">${esc(p.number??'?')}</span> ${esc(p.name)}</button></th><td id="recorded-quality-${p.id}"></td></tr>`).join('')}</tbody></table></section></div><div class="recorded-legend" aria-label="Position quality legend"><span><i class="quality-swatch detected"></i> Solid circle: source detected</span><span><i class="quality-swatch estimated"></i> Dashed circle: source estimated</span><span><i class="quality-swatch unknown">?</i> Dotted square: quality unknown</span><span>Outer ring: selected player · Ball uses the same quality outlines</span></div><div class="recorded-timeline"><label for="recorded-range">Sample clock <span>First half · no interpolation</span></label><input id="recorded-range" type="range" min="${s.start}" max="${s.end}" step="${s.cadence}" value="${s.start}"><div class="recorded-coverage" aria-label="Sample coverage bands">${model.coverage.map(c=>`<span class="${c.value}" style="flex:${c.slots}" title="${esc(c.value)} ${model.clock(c.start)}–${model.clock(c.end)}"></span>`).join('')}</div><div class="replay-controls"><button id="recorded-play">▶ Play</button><button id="recorded-start">← Start</button><button id="recorded-end">04:00.0 · End</button></div><p id="recorded-coverage-current"></p><div id="recorded-gap-actions" hidden><button id="recorded-previous">Return to previous available positions</button><button id="recorded-next">Skip to next available positions</button><button id="recorded-continue">Continue clock through gap</button><p id="recorded-gap-navigation"></p></div><p id="recorded-announcement" role="status" aria-live="polite"></p><details class="recorded-coverage-details"><summary>Coverage and display details</summary><ul>${model.coverage.map(c=>`<li>${model.clock(c.start)}–${model.clock(c.end)} inclusive: ${esc(c.value.replaceAll('-',' '))}, ${c.slots} sampled slots.</li>`).join('')}</ul><p>Bounds describe sampled coverage, not exact real-world outage duration. A missing source frame differs from an existing frame with empty or partial positions. Ball availability is independent. No trails or interpolation. Raw out-of-bounds positions are preserved in a padded viewport.</p><p>Source: ${s.pitch.length} × ${s.pitch.width} metres, centre origin. Display axes: +x right, +y up. Source first-half home direction: ${esc(s.pitch.homeTeamSide?.[0]??'unknown')}. The display does not infer a new direction or correct coordinates.</p></details></div><section class="recorded-events" aria-labelledby="recorded-events-heading"><div class="recorded-events-heading"><h3 id="recorded-events-heading">Completed possessions</h3><span>Recorded analysis</span></div><p id="recorded-event-gap"></p><p id="recorded-event-empty">No completed annotations are available in this curated selection at this cursor. This does not mean no football happened.</p><ol id="recorded-event-list"></ol></section><button class="ask-moment" id="recorded-ask-moment">Ask about this player at this moment ↗</button><small>Retrospective, source-derived · Source detections and estimates, not ground truth. Small curated possession annotations only. Score, tactics, speed and distance are unavailable.</small></div></details>`;}
function message(text,user,byline,source){return `<div class="message ${user?'user':''}">${user?'':`<div class="byline">${esc(byline)}</div>`}<p>${esc(text)}</p>${user?'':`<span class="source">${esc(source)}</span>`}</div>`;}
function context({state,stateClass='past',title,subtitle,sources}){return `<div class="context-strip"><div><span class="state-label ${esc(stateClass)}">${esc(state)}</span><strong>${title}</strong><small>${subtitle}</small></div>${sources}</div>`;}
function journey(left,right){return `<div class="journey-bar"><div>${left}</div>${right}</div>`;}
function fixture({tag='button',attrs='',date,status,statusClass='',homeCrest,home,score,clock,awayCrest,away,venue,action}){return `<${tag} class="fixture" ${attrs}><div class="fixture-top"><span>${date}</span><span class="status ${statusClass}">${status}</span></div><div class="fixture-teams"><div>${homeCrest}<span class="team-name">${home}</span></div><div class="score">${score}<small>${clock}</small></div><div>${awayCrest}<span class="team-name">${away}</span></div></div><div class="fixture-bottom"><span>${venue}</span><strong>${action}</strong></div></${tag}>`;}
const api={shell,pitch,message,context,journey,fixture,esc};if(typeof module!=='undefined'&&module.exports)module.exports=api;else{root.MatchWorkspace=api;document.querySelector('#demo-workspace').innerHTML=shell();document.querySelector('#historical-match').innerHTML=shell(true);}
})(typeof window!=='undefined'?window:globalThis);
